insert into public.paginas (id, contenido) values ('contacto', '{"seo":{"titulo":{"es":"Contacto · Wanna Go Colombia, Medellín","en":"Contact · Wanna Go Colombia, Medellín"},"descripcion":"Escríbenos por WhatsApp al +57 312 289 9185 o a wannagoco@gmail.com. Oficina en El Poblado, Medellín. Diseñamos tu viaje por Colombia.","foto":"medellin.jpg"},"portada":{"foto":"medellin.jpg","alt":{"es":"Medellín iluminada al atardecer, rodeada de montañas","en":"Medellín lit up at dusk, surrounded by mountains"},"etiqueta":{"es":"Contacto","en":"Contact"},"titulo":{"es":"Diseñemos tu próximo viaje","en":"Let''s plan your next trip"},"texto":{"es":"Cuéntanos qué te mueve y te proponemos un itinerario a tu medida. Respondemos por WhatsApp.","en":"Tell us what moves you and we''ll propose an itinerary made for you. We reply on WhatsApp."}},"canales":{"ceja":{"es":"Canales","en":"Channels"},"titulo":{"es":"Hablemos de tu viaje","en":"Let''s talk about your trip"},"texto":{"es":"Cuéntanos qué te mueve y te proponemos un itinerario a tu medida. Respondemos por WhatsApp.","en":"Tell us what moves you and we''ll propose an itinerary made for you. We reply on WhatsApp."}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('destinos', '{"seo":{"titulo":{"es":"Destinos en Colombia para viajar con propósito · Wanna Go","en":"Destinations in Colombia for purposeful travel · Wanna Go"},"descripcion":"Guatapé, Comuna 13, Cartagena, Valle de Cocora, Tayrona y el Eje Cafetero: viajes por Colombia diseñados desde Medellín por Wanna Go.","foto":"guatape.jpg"},"portada":{"foto":"guatape.jpg","alt":{"es":"Embalse de Guatapé con sus islas verdes visto desde lo alto","en":"Guatapé reservoir and its green islands seen from above"},"etiqueta":{"es":"Destinos en Colombia","en":"Destinations in Colombia"},"titulo":{"es":"Conoce Colombia desde adentro","en":"Discover Colombia from the inside"},"texto":{"es":"Lugares que diseñamos con cariño, desde Medellín hasta el Caribe. Cada uno se puede combinar en un viaje a tu medida.","en":"Places we design with care, from Medellín to the Caribbean. Each one can be combined into a tailor-made trip."}},"listado":{"ceja":{"es":"Destinos","en":"Destinations"},"titulo":{"es":"Elige por dónde empezar","en":"Choose where to start"}},"cierre":{"foto":"medellin.jpg","titulo":{"es":"¿No sabes cuál elegir? Te ayudamos","en":"Can''t decide? We''ll help"},"whatsapp":"Hola Wanna Go, quiero ideas para viajar por Colombia."}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('eventos-corporativos', '{"seo":{"titulo":{"es":"Eventos corporativos en Medellín y Antioquia · Wanna Go","en":"Corporate events in Medellín and Antioquia · Wanna Go"},"descripcion":"Incentivos, convenciones y experiencias de equipo en Medellín y Antioquia, con logística completa y experiencias locales con propósito.","foto":"medellin-montanas.jpg"},"portada":{"foto":"medellin-montanas.jpg","alt":{"es":"Edificios de Medellín frente a las montañas","en":"Medellín buildings against the mountains"},"etiqueta":{"es":"Empresas","en":"Companies"},"titulo":{"es":"Eventos corporativos en Medellín y Antioquia","en":"Corporate events in Medellín and Antioquia"},"texto":{"es":"Incentivos, convenciones y experiencias de equipo con logística completa en Medellín y Antioquia.","en":"Incentive trips, conventions and team experiences with full logistics in Medellín and Antioquia."},"whatsapp":"Hola Wanna Go, quiero cotizar un evento corporativo."},"intro":{"ceja":{"es":"01 · Para empresas","en":"01 · For companies"},"titulo":{"es":"Experiencias que unen equipos","en":"Experiences that bring teams together"},"parrafos":[{"es":"Diseñamos viajes de incentivo, convenciones y salidas de equipo que muestran Medellín y Antioquia desde adentro, con la misma calidez con la que recibimos a nuestros viajeros.","en":"We design incentive trips, conventions and team outings that show Medellín and Antioquia from the inside, with the same warmth we offer every traveler."},{"es":"Nos encargamos de la logística completa: transporte, alojamiento, espacios, alimentación y experiencias locales, con un solo contacto para todo.","en":"We handle the full logistics: transport, lodging, venues, catering and local experiences, with a single point of contact."}],"foto":"medellin.jpg","alt":{"es":"Medellín iluminada al atardecer, rodeada de montañas","en":"Medellín lit up at dusk, surrounded by mountains"}},"pasos":{"ceja":{"es":"02 · Qué organizamos","en":"02 · What we organize"},"titulo":{"es":"Formatos para tu empresa","en":"Formats for your company"},"items":[{"titulo":{"es":"Viajes de incentivo","en":"Incentive trips"},"texto":{"es":"Premia a tu equipo con experiencias que no olvidará.","en":"Reward your team with experiences they won''t forget."}},{"titulo":{"es":"Convenciones y reuniones","en":"Conventions and meetings"},"texto":{"es":"Espacios, transporte y agenda coordinados.","en":"Venues, transport and agenda, all coordinated."}},{"titulo":{"es":"Integración de equipos","en":"Team building"},"texto":{"es":"Actividades con propósito en la ciudad y la naturaleza.","en":"Purposeful activities in the city and in nature."}},{"titulo":{"es":"Experiencias para visitantes","en":"Experiences for visitors"},"texto":{"es":"Recibe a clientes y socios con lo mejor de Medellín.","en":"Welcome clients and partners with the best of Medellín."}}]},"destinos":{"ceja":{"es":"03 · Experiencias","en":"03 · Experiences"},"titulo":{"es":"Ideas en Medellín y Antioquia","en":"Ideas in Medellín and Antioquia"},"lista":["comuna-13","guatape","plazas-de-mercado"]},"resenas":{"ceja":{"es":"Lo que dicen","en":"What people say"},"titulo":{"es":"Historias de quienes viajaron con nosotros","en":"Stories from people who traveled with us"}},"cierre":{"foto":"medellin-montanas.jpg","titulo":{"es":"Cuéntanos de tu evento","en":"Tell us about your event"},"whatsapp":"Hola Wanna Go, quiero cotizar un evento corporativo."}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('inicio', '{"seo":{"titulo":{"es":"Wanna Go Colombia · Agencia de viajes con propósito en Medellín","en":"Wanna Go Colombia · Purposeful travel agency in Medellín"},"descripcion":"Wanna Go: agencia de turismo receptivo en Medellín. Viajes a la medida, viajes grupales y eventos corporativos con propósito.","foto":"medellin.jpg"},"portada":{"foto":"medellin.jpg","alt":{"es":"Medellín iluminada al atardecer, rodeada de montañas","en":"Medellín lit up at dusk, surrounded by mountains"},"etiqueta":{"es":"Agencia de turismo receptivo · Medellín","en":"Inbound travel agency · Medellín"},"titulo":{"es":"Colombia se vive mejor en buena compañía","en":"Colombia is best experienced in good company"},"texto":{"es":"Diseñamos viajes a la medida, viajes grupales y eventos corporativos con un sello claro: viajes con propósito, donde el destino transforma y la compañía hace que cada viaje sea memorable.","en":"We design tailor-made trips, group trips and corporate events with one clear signature: purposeful travel, where the destination transforms you and the company makes every trip memorable."},"boton1":{"es":"Ver próximos viajes","en":"See upcoming trips"},"boton2":{"es":"Diseñar mi viaje","en":"Plan my trip"}},"viajes":{"ceja":{"es":"01 · Nuestros viajes","en":"01 · Our trips"},"titulo":{"es":"Elige tu próximo viaje","en":"Choose your next trip"},"cta_etiqueta":{"es":"A tu ritmo","en":"At your pace"},"cta_titulo":{"es":"Diseña tu propio viaje","en":"Design your own trip"},"cta_boton":{"es":"Empezar","en":"Get started"}},"nosotros":{"ceja":{"es":"02 · Quiénes somos","en":"02 · Who we are"},"titulo":{"es":"Viajes con propósito","en":"Purposeful travel"},"parrafos":[{"es":"Wanna Go es una agencia de turismo receptivo con sede en Medellín, fundada en 2019 por María Lucía Vásquez Cock, Luchy.","en":"Wanna Go is an inbound travel agency based in Medellín, founded in 2019 by María Lucía Vásquez Cock, Luchy."},{"es":"Huimos del turismo masivo y de lo predecible. Te mostramos cada destino desde adentro, con su gente, su cocina y sus paisajes, para que vuelvas distinto de como te fuiste.","en":"We steer clear of mass tourism and the predictable. We show you each destination from the inside, through its people, its food and its landscapes, so you come home different from how you left."}],"enlace":{"es":"Conocer más","en":"Learn more"},"cifras":[{"valor":"2019","texto":{"es":"Año de fundación","en":"Year founded"}},{"valor":"RNT 65568","texto":{"es":"Registro Nacional de Turismo","en":"National Tourism Registry"}},{"valor":"Medellín","texto":{"es":"Colombia","en":"Colombia"}}],"foto":"guatape-calle.jpg","alt":{"es":"Calle con fachadas de colores y zócalos en Guatapé","en":"Street with colorful facades and zócalos in Guatapé"}},"experiencias":{"ceja":{"es":"03 · Lo que hacemos","en":"03 · What we do"},"titulo":{"es":"Tres formas de viajar con nosotros","en":"Three ways to travel with us"},"boton":{"es":"Conocer más","en":"Learn more"},"tarjetas":[{"enlace":"viajes-a-la-medida/","foto":"salento.jpg","alt":{"es":"Palmas de cera en el valle de Cocora","en":"Wax palms in the Cocora Valley"},"etiqueta":{"es":"A tu ritmo","en":"At your pace"},"titulo":{"es":"Viajes a la medida","en":"Tailor-made trips"},"texto":{"es":"Itinerarios privados diseñados alrededor de lo que te mueve: café, naturaleza, cocina, arte o descanso.","en":"Private itineraries designed around what moves you: coffee, nature, food, art or rest."}},{"enlace":"viajes-grupales/","foto":"grupo-atardecer.jpg","alt":{"es":"Grupo de viajeros contemplando el atardecer","en":"Group of travelers watching the sunset"},"etiqueta":{"es":"Grupos pequeños","en":"Small groups"},"titulo":{"es":"Viajes grupales","en":"Group trips"},"texto":{"es":"Salidas acompañadas en Colombia y el mundo, con anfitriona Wanna Go de principio a fin.","en":"Hosted departures in Colombia and around the world, with a Wanna Go host from start to finish."}},{"enlace":"eventos-corporativos/","foto":"medellin-montanas.jpg","alt":{"es":"Edificios de Medellín frente a las montañas","en":"Medellín buildings against the mountains"},"etiqueta":{"es":"Empresas","en":"Companies"},"titulo":{"es":"Eventos corporativos","en":"Corporate events"},"texto":{"es":"Incentivos, convenciones y experiencias de equipo con logística completa en Medellín y Antioquia.","en":"Incentive trips, conventions and team experiences with full logistics in Medellín and Antioquia."}}]},"pilares":{"ceja":{"es":"04 · Nuestro sello","en":"04 · Our signature"},"titulo":{"es":"Pilares de los viajes con propósito","en":"The pillars of purposeful travel"},"items":[{"titulo":{"es":"Impacto local y sostenibilidad","en":"Local impact and sustainability"},"texto":{"es":"Fomentamos el comercio local, respetamos la cultura y protegemos el entorno natural.","en":"We support local businesses, respect the culture and protect the natural environment."}},{"titulo":{"es":"Transformación personal","en":"Personal transformation"},"texto":{"es":"Creamos espacios para aprender, reconectar, hacer una pausa y crecer.","en":"We create space to learn, reconnect, pause and grow."}},{"titulo":{"es":"Autenticidad y exclusividad","en":"Authenticity and exclusivity"},"texto":{"es":"Experiencias genuinas, lejos del turismo masivo y acelerado.","en":"Genuine experiences, far from rushed mass tourism."}},{"titulo":{"es":"Hospitalidad cálida","en":"Warm hospitality"},"texto":{"es":"Un sello personal de cuidado y detalle en cada punto del viaje.","en":"A personal touch of care and detail at every point of the trip."}}]},"resenas":{"ceja":{"es":"05 · Lo que dicen","en":"05 · What people say"},"titulo":{"es":"Historias de quienes viajaron con nosotros","en":"Stories from people who traveled with us"}},"fundadora":{"ceja":{"es":"06 · Fundadora","en":"06 · Founder"},"cita":{"es":"“Creo en los viajes que transforman: los que te sientan a la mesa de una familia local y te devuelven a casa con historias.”","en":"“I believe in trips that transform you: the ones that seat you at a local family''s table and send you home with stories.”"},"nombre":"María Lucía Vásquez Cock · Luchy","cargo":{"es":"Fundadora y diseñadora de experiencias","en":"Founder and experience designer"}},"frase":{"foto":"guatape.jpg","texto":{"es":"“Viajar con propósito, volver con historias.”","en":"“Travel with purpose, come home with stories.”"},"firma":"Wanna Go Colombia"},"contacto":{"ceja":{"es":"07 · Contacto","en":"07 · Contact"},"titulo":{"es":"Diseñemos tu próximo viaje","en":"Let''s plan your next trip"},"texto":{"es":"Cuéntanos qué te mueve y te proponemos un itinerario a tu medida. Respondemos por WhatsApp.","en":"Tell us what moves you and we''ll propose an itinerary made for you. We reply on WhatsApp."}}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
insert into public.paginas (id, contenido) values ('nosotros', '{"seo":{"titulo":{"es":"Quiénes somos · Wanna Go, agencia de viajes en Medellín","en":"About us · Wanna Go, travel agency in Medellín"},"descripcion":"Wanna Go es una agencia de turismo receptivo en Medellín fundada en 2019 por Luchy Vásquez. Viajes con propósito, auténticos y con hospitalidad cálida.","foto":"guatape-calle.jpg"},"portada":{"foto":"guatape-calle.jpg","alt":{"es":"Calle con fachadas de colores y zócalos en Guatapé","en":"Street with colorful facades and zócalos in Guatapé"},"etiqueta":{"es":"Quiénes somos","en":"About us"},"titulo":{"es":"Viajes con propósito desde Medellín","en":"Purposeful travel from Medellín"},"texto":{"es":"Somos una agencia de turismo receptivo fundada en 2019. Te mostramos Colombia desde adentro: con su gente, su cocina y sus paisajes.","en":"We are an inbound travel agency founded in 2019. We show you Colombia from the inside: its people, its food and its landscapes."}},"historia":{"ceja":{"es":"01 · Nuestra historia","en":"01 · Our story"},"titulo":{"es":"Viajes con propósito","en":"Purposeful travel"},"parrafos":[{"es":"Wanna Go es una agencia de turismo receptivo con sede en Medellín, fundada en 2019 por María Lucía Vásquez Cock, Luchy.","en":"Wanna Go is an inbound travel agency based in Medellín, founded in 2019 by María Lucía Vásquez Cock, Luchy."},{"es":"Huimos del turismo masivo y de lo predecible. Te mostramos cada destino desde adentro, con su gente, su cocina y sus paisajes, para que vuelvas distinto de como te fuiste.","en":"We steer clear of mass tourism and the predictable. We show you each destination from the inside, through its people, its food and its landscapes, so you come home different from how you left."}],"cifras":[{"valor":"2019","texto":{"es":"Año de fundación","en":"Year founded"}},{"valor":"RNT 65568","texto":{"es":"Registro Nacional de Turismo","en":"National Tourism Registry"}},{"valor":"Medellín","texto":{"es":"Colombia","en":"Colombia"}}],"foto":"comuna13.jpg","alt":{"es":"Casas de colores y murales en las laderas de la Comuna 13","en":"Colorful houses and murals on the hillsides of Comuna 13"}},"fundadora":{"ceja":{"es":"02 · Fundadora","en":"02 · Founder"},"cita":{"es":"“Creo en los viajes que transforman: los que te sientan a la mesa de una familia local y te devuelven a casa con historias.”","en":"“I believe in trips that transform you: the ones that seat you at a local family''s table and send you home with stories.”"},"nombre":"María Lucía Vásquez Cock · Luchy","cargo":{"es":"Fundadora y diseñadora de experiencias","en":"Founder and experience designer"}},"pilares":{"ceja":{"es":"03 · Nuestro sello","en":"03 · Our signature"},"titulo":{"es":"Pilares de los viajes con propósito","en":"The pillars of purposeful travel"},"items":[{"titulo":{"es":"Impacto local y sostenibilidad","en":"Local impact and sustainability"},"texto":{"es":"Fomentamos el comercio local, respetamos la cultura y protegemos el entorno natural.","en":"We support local businesses, respect the culture and protect the natural environment."}},{"titulo":{"es":"Transformación personal","en":"Personal transformation"},"texto":{"es":"Creamos espacios para aprender, reconectar, hacer una pausa y crecer.","en":"We create space to learn, reconnect, pause and grow."}},{"titulo":{"es":"Autenticidad y exclusividad","en":"Authenticity and exclusivity"},"texto":{"es":"Experiencias genuinas, lejos del turismo masivo y acelerado.","en":"Genuine experiences, far from rushed mass tourism."}},{"titulo":{"es":"Hospitalidad cálida","en":"Warm hospitality"},"texto":{"es":"Un sello personal de cuidado y detalle en cada punto del viaje.","en":"A personal touch of care and detail at every point of the trip."}}]},"resenas":{"ceja":{"es":"Lo que dicen","en":"What people say"},"titulo":{"es":"Historias de quienes viajaron con nosotros","en":"Stories from people who traveled with us"}},"cierre":{"foto":"grupo-atardecer.jpg","titulo":{"es":"Colombia se vive mejor en buena compañía","en":"Colombia is best experienced in good company"},"whatsapp":"Hola Wanna Go, quiero conocerlos."}}'::jsonb) on conflict (id) do update set contenido = excluded.contenido;
